"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

/**
 * TableOfContents — an anchor-link nav list with indent levels and an
 * active-item state (drive `active` from your own scroll-spy).
 */
export interface TocItem {
  id: string;
  label: React.ReactNode;
  level?: number;
}

export interface TableOfContentsProps extends React.HTMLAttributes<HTMLElement> {
  items: TocItem[];
  active?: string;
}

const TableOfContents = React.forwardRef<HTMLElement, TableOfContentsProps>(
  ({ className, items, active, ...props }, ref) => (
    <nav ref={ref} aria-label="Table of contents" className={cn("flex flex-col gap-0.5 font-sans", className)} {...props}>
      {items.map((item) => {
        const isActive = item.id === active;
        return (
          <a
            key={item.id}
            href={`#${item.id}`}
            aria-current={isActive ? "location" : undefined}
            style={{ paddingInlineStart: `${((item.level ?? 1) - 1) * 12 + 12}px` }}
            className={cn(
              "-ms-px border-s py-1.5 text-body-sm outline-none transition-colors",
              isActive ? "border-action font-medium text-action" : "border-transparent text-muted-foreground hover:text-foreground",
            )}
          >
            {item.label}
          </a>
        );
      })}
    </nav>
  ),
);
TableOfContents.displayName = "TableOfContents";

export { TableOfContents };

import { type ClassValue, clsx } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

// The Material type-scale utilities (`text-label-md`, `text-body-sm`, …) come
// from `fontSize` in tailwind.config.ts. Without this, tailwind-merge reads them
// as text *colours* and drops a real colour class (`text-primary-foreground`).
const twMerge = extendTailwindMerge({
  extend: {
    classGroups: {
      "font-size": [
        {
          text: [
            "display-lg", "display-md", "display-sm",
            "headline-lg", "headline-md", "headline-sm",
            "title-lg", "title-md", "title-sm", "title-dialog",
            "label-lg", "label-md", "label-sm",
            "body-lg", "body-md", "body-sm",
          ],
        },
      ],
    },
  },
});

/** Merges Tailwind class names, resolving conflicts (clsx + tailwind-merge). */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
